import React from 'react';
import { MetadataLabel } from '@/components/scilent/metadata-label/MetadataLabel';
import { formatArtistNames } from '@/lib/scilent/utils/artist';
import { ArtistLabelProps } from '@/lib/scilent/types/artist';

/**
 * ArtistLabel component for displaying artist names with various formatting options
 *
 * @example
 * // Single artist
 * <ArtistLabel artists="Taylor Swift" />
 *
 * @example
 * // Multiple artists
 * <ArtistLabel artists={["Drake", "Future", "Metro Boomin"]} />
 *
 * @example
 * // Custom delimiter
 * <ArtistLabel artists={["Kendrick Lamar", "SZA"]} delimiter=" & " />
 *
 * @example
 * // With truncation
 * <ArtistLabel
 *   artists="A very long artist name that will be truncated"
 *   truncate={true}
 *   truncationType="middle"
 *   maxLength={20}
 * />
 *
 * @example
 * // With custom styling
 * <ArtistLabel
 *   artists="Taylor Swift"
 *   style={{ fontWeight: 'bold', fontStyle: 'italic', color: '#1DB954', fontSize: '18px' }}
 * />
 */
export const ArtistLabel: React.FC<ArtistLabelProps> = ({
  artists,
  delimiter = ', ',
  truncate = true,
  truncationType = 'end',
  maxLength,
  as = 'span',
  className = '',
  style = {},
  onClick,
  ...rest // Add this to capture additional props
}) => {
  // Format the artist names
  const formattedArtists = formatArtistNames(artists, delimiter);

  // Use the MetadataLabel component with the formatted artist names
  return (
    <MetadataLabel
      text={formattedArtists}
      truncate={truncate}
      truncationType={truncationType}
      maxLength={maxLength}
      as={as}
      className={`artist-label ${className}`}
      style={style}
      onClick={onClick}
      {...rest} // Spread additional props
    />
  );
};

export default ArtistLabel;

import React, { useRef } from 'react';
import * as RadixTooltip from '@radix-ui/react-tooltip';
import { truncateText } from '@/lib/scilent/utils/metadata';

/**
 * Props for the MetadataLabel component
 */
export interface MetadataLabelProps {
  /**
   * Text content to display
   */
  text: string;

  /**
   * Whether to truncate the text when it exceeds maxLength
   * @default true
   */
  truncate?: boolean;

  /**
   * Type of truncation to apply
   * @default "end"
   */
  truncationType?: 'none' | 'end' | 'middle';

  /**
   * Maximum number of characters before truncation
   * @default undefined (no truncation unless specified)
   */
  maxLength?: number;

  /**
   * HTML element to render as
   * @default "span"
   */
  as?: 'span' | 'div' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';

  /**
   * Additional CSS class name
   */
  className?: string;

  /**
   * Additional inline styles
   * Use this for all styling needs (fontWeight, fontStyle, color, fontSize, etc.)
   */
  style?: React.CSSProperties;

  /**
   * Click handler
   */
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;

  /**
   * Additional HTML attributes
   */
  [key: string]: any;
}

/**
 * MetadataLabel component for displaying text with truncation options
 *
 * @example
 * // Basic usage
 * <MetadataLabel text="Some text content" />
 *
 * @example
 * // With truncation
 * <MetadataLabel
 *   text="A very long text that will be truncated"
 *   truncate={true}
 *   truncationType="middle"
 *   maxLength={20}
 * />
 *
 * @example
 * // With custom styling
 * <MetadataLabel
 *   text="Styled text"
 *   style={{ fontWeight: 'bold', fontStyle: 'italic', color: '#1DB954', fontSize: '18px' }}
 * />
 */
export const MetadataLabel: React.FC<MetadataLabelProps> = ({
  text,
  truncate = true,
  truncationType = 'end',
  maxLength,
  as = 'span',
  className = '',
  style = {},
  onClick,
  ...rest
}) => {
  const textRef = useRef<HTMLElement>(null);

  // Apply truncation if needed
  let displayText = text;
  let isTruncated = false;

  if (truncate && maxLength && text.length > maxLength) {
    displayText = truncateText(text, maxLength, truncationType);
    isTruncated = true;
  }

  // Combine styles
  const combinedStyles: React.CSSProperties = {
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    ...style,
  };

  // Create the component based on the 'as' prop
  const Component = as;

  // If truncated, wrap in tooltip to show full text
  if (isTruncated) {
    return (
      <RadixTooltip.Provider>
        <RadixTooltip.Root>
          <RadixTooltip.Trigger asChild>
            <Component
              ref={textRef as React.Ref<HTMLDivElement>}
              className={`metadata-label ${className}`}
              style={combinedStyles}
              onClick={onClick}
              data-full-text={text}
              {...rest}
            >
              {displayText}
            </Component>
          </RadixTooltip.Trigger>
          <RadixTooltip.Portal>
            <RadixTooltip.Content
              className="metadata-label-tooltip"
              sideOffset={5}
              style={{
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                color: 'white',
                borderRadius: '4px',
                padding: '8px 12px',
                fontSize: '14px',
                maxWidth: '300px',
                zIndex: 1000,
              }}
            >
              {text}
              <RadixTooltip.Arrow style={{ fill: 'rgba(0, 0, 0, 0.8)' }} />
            </RadixTooltip.Content>
          </RadixTooltip.Portal>
        </RadixTooltip.Root>
      </RadixTooltip.Provider>
    );
  }

  // If not truncated, render normally
  return (
    <Component
      ref={textRef as React.Ref<HTMLDivElement>}
      className={`metadata-label ${className}`}
      style={combinedStyles}
      onClick={onClick}
      data-full-text={text}
      {...rest}
    >
      {displayText}
    </Component>
  );
};

export default MetadataLabel;

import { MetadataLabelProps } from '@/components/scilent/metadata-label/MetadataLabel';

/**
 * Truncation options for text elements
 */
export type TruncationType = 'none' | 'end' | 'middle';

/**
 * Artist label configuration
 */
export interface ArtistLabelProps extends Omit<MetadataLabelProps, 'text'> {
  /**
   * Artist name or array of artist names
   */
  artists: string | string[];

  /**
   * Delimiter to use when joining multiple artist names
   * @default ", "
   */
  delimiter?: string;

  /**
   * Whether to truncate the text when it overflows
   * @default true
   */
  truncate?: boolean;

  /**
   * Type of truncation to apply
   * @default "end"
   */
  truncationType?: TruncationType;

  /**
   * Maximum number of characters before truncation
   * @default undefined (no truncation unless specified)
   */
  maxLength?: number;

  /**
   * HTML element to render as
   * @default "span"
   */
  as?: 'span' | 'div' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';

  /**
   * Additional CSS class name
   */
  className?: string;

  /**
   * Additional inline styles
   * Use this for all styling needs (fontWeight, fontStyle, color, fontSize, etc.)
   */
  style?: React.CSSProperties;

  /**
   * Click handler
   */
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;
}

/**
 * Format artist names with a delimiter
 * @param artists Single artist name or array of artist names
 * @param delimiter Delimiter to use when joining multiple artist names
 * @returns Formatted artist name string
 */
export function formatArtistNames(artists: string | string[], delimiter: string = ', '): string {
  if (typeof artists === 'string') {
    return artists;
  }

  if (!artists.length) {
    return '';
  }

  // Filter out empty strings and join with delimiter
  return artists.filter(artist => artist.trim() !== '').join(delimiter);
}

/**
 * Truncate text at the end with ellipsis
 * @param text Text to truncate
 * @param maxLength Maximum length before truncation
 * @returns Truncated text
 */
export function truncateTextEnd(text: string, maxLength: number): string {
  if (!text || text.length <= maxLength) {
    return text;
  }

  return `${text.slice(0, maxLength - 1)}…`;
}

/**
 * Truncate text in the middle with ellipsis
 * @param text Text to truncate
 * @param maxLength Maximum length before truncation
 * @returns Truncated text
 */
export function truncateTextMiddle(text: string, maxLength: number): string {
  if (!text || text.length <= maxLength) {
    return text;
  }

  // Keep more characters at the beginning than at the end
  const startChars = Math.ceil(maxLength * 0.6);
  const endChars = maxLength - startChars - 1; // -1 for the ellipsis

  return `${text.slice(0, startChars)}…${text.slice(text.length - endChars)}`;
}

/**
 * Truncate text based on specified truncation type
 * @param text Text to truncate
 * @param maxLength Maximum length before truncation
 * @param type Type of truncation to apply
 * @returns Truncated text
 */
export function truncateText(
  text: string,
  maxLength: number,
  type: 'none' | 'end' | 'middle' = 'end'
): string {
  if (type === 'none' || !text || text.length <= maxLength) {
    return text;
  }

  if (type === 'middle') {
    return truncateTextMiddle(text, maxLength);
  }

  return truncateTextEnd(text, maxLength);
}
